SELECT city,revenue FROM (SELECT city,amount AS revenue FROM doris_book.orders_intro_v1)t WHERE revenue>100 ORDER BY revenue; SELECT city,amount FROM doris_book.orders_intro_v1 WHERE amount>100 ORDER BY amount; SELECT COUNT(*) FROM (SELECT order_id,amount AS revenue FROM doris_book.orders_intro_v1 ORDER BY order_id LIMIT 2)t WHERE revenue>100; SELECT COUNT(*) FROM (SELECT order_id,amount FROM doris_book.orders_intro_v1 WHERE amount>100 ORDER BY order_id LIMIT 2)t;
